#include <madron/cepstral/CepstralMorph.h>

#include <algorithm>
#include <cmath>

namespace madron::cepstral {
bool CepstralMorph::prepare(const dsp::ProcessSpec& spec) {
    prepared_=dsp::isSupportedStereoOrMono(spec); if(!prepared_) return false; spec_=spec; preparedSelection_=std::clamp(fftSelection_.load(),0,3); auto& variant=variant_; variant.size=sizes_[static_cast<std::size_t>(preparedSelection_)]; if(!variant.cepstralFft.prepare(variant.size)){prepared_=false;return false;} variant.channels.clear();variant.channels.resize(spec.channelCount);for(auto& channel:variant.channels){if(!channel.a.prepare(variant.size,overlap)||!channel.b.prepare(variant.size,overlap)){prepared_=false;return false;}channel.cepA.assign(variant.size,{});channel.cepB.assign(variant.size,{});channel.envA.assign(variant.size,{});channel.envB.assign(variant.size,{});channel.detailA.assign(variant.size,{});channel.detailB.assign(variant.size,{});}
    if(!inputB_.prepare(spec)){prepared_=false;return false;}internalBBuffer_.assign(spec.channelCount,std::vector<float>(spec.maximumBlockSize,0.0f));internalBPointers_.resize(spec.channelCount);internalBConstPointers_.resize(spec.channelCount);for(std::size_t c=0;c<spec.channelCount;++c){internalBPointers_[c]=internalBBuffer_[c].data();internalBConstPointers_[c]=internalBBuffer_[c].data();} reset();return true;
}
void CepstralMorph::reset() noexcept { for(auto& channel:variant_.channels){channel.a.reset();channel.b.reset();channel.smoothEnvelope=envelopeBlend_.load();channel.smoothDetail=detailBlend_.load();channel.smoothPhase=phaseBlend_.load();} inputB_.reset();for(auto& b:internalBBuffer_)std::fill(b.begin(),b.end(),0.0f); }
void CepstralMorph::setParameters(const Parameters& p) noexcept { const int n=std::clamp(static_cast<int>(p.fftSize),0,3);fftSelection_.store(n);envelopeBlend_.store(dsp::clampFinite(p.envelopeBlend,0.0f,1.0f));detailBlend_.store(dsp::clampFinite(p.detailBlend,0.0f,1.0f));phaseBlend_.store(dsp::clampFinite(p.phaseBlend,0.0f,1.0f));phaseMode_.store(std::clamp(static_cast<int>(p.phaseMode),0,3)); }
Parameters CepstralMorph::parameters() const noexcept { return {static_cast<FFTSize>(fftSelection_.load()),envelopeBlend_.load(),detailBlend_.load(),phaseBlend_.load(),static_cast<PhaseMode>(phaseMode_.load())}; }
dsp::ProcessResult CepstralMorph::process(const dsp::AudioBufferView& inputA,const dsp::MutableAudioBufferView& output) noexcept { if(!prepared_)return dsp::ProcessResult::NotPrepared; if(inputA.sampleCount>spec_.maximumBlockSize)return dsp::ProcessResult::InvalidBuffer; const dsp::MutableAudioBufferView b{internalBPointers_.data(),spec_.channelCount,inputA.sampleCount};const auto result=inputB_.process(inputA,b);if(result!=dsp::ProcessResult::Ok)return result;const dsp::AudioBufferView internal{internalBConstPointers_.data(),spec_.channelCount,inputA.sampleCount};return processImpl(inputA,internal,output); }
dsp::ProcessResult CepstralMorph::process(const dsp::AudioBufferView& a,const dsp::AudioBufferView& b,const dsp::MutableAudioBufferView& output) noexcept { return processImpl(a,b,output); }
dsp::ProcessResult CepstralMorph::processImpl(const dsp::AudioBufferView& inputA,const dsp::AudioBufferView& inputB,const dsp::MutableAudioBufferView& output) noexcept {
    if(!prepared_)return dsp::ProcessResult::NotPrepared;if(!inputA.isValid()||!inputB.isValid()||!output.isValid()||inputA.channelCount!=spec_.channelCount||inputB.channelCount!=spec_.channelCount||output.channelCount!=spec_.channelCount||inputA.sampleCount!=inputB.sampleCount||inputA.sampleCount!=output.sampleCount||inputA.sampleCount>spec_.maximumBlockSize)return dsp::ProcessResult::InvalidBuffer;
    for(std::size_t sample=0;sample<inputA.sampleCount;++sample)for(std::size_t channel=0;channel<spec_.channelCount;++channel){auto& state=variant_.channels[channel];(void)state.b.processSample(inputB.channels[channel][sample],nullptr,nullptr);CallbackContext context{this,&variant_,&state};output.channels[channel][sample]=state.a.processSample(inputA.channels[channel][sample],&context,&CepstralMorph::processSpectrum);}return dsp::ProcessResult::Ok;
}
std::size_t CepstralMorph::getLatencySamples() const noexcept { return sizes_[static_cast<std::size_t>(preparedSelection_)]; }
void CepstralMorph::processSpectrum(void* opaque,const std::span<dsp::Complex> spectrum) noexcept {auto& c=*static_cast<CallbackContext*>(opaque);c.owner->morphSpectrum(*c.variant,*c.channel,spectrum);}
void CepstralMorph::morphSpectrum(Variant& variant,Channel& channel,const std::span<dsp::Complex> spectrum) noexcept {
    const std::size_t n=variant.size, cutoff=std::min<std::size_t>(25,n/2);const auto b=channel.b.spectrum();for(std::size_t k=0;k<n;++k){channel.cepA[k]={std::log(std::max(1.0e-8f,std::abs(spectrum[k]))),0.0f};channel.cepB[k]={std::log(std::max(1.0e-8f,std::abs(b[k]))),0.0f};}variant.cepstralFft.transform(channel.cepA,true);variant.cepstralFft.transform(channel.cepB,true);for(std::size_t q=0;q<n;++q){const bool low=q<=cutoff||q>=n-cutoff;channel.envA[q]=low?channel.cepA[q]:dsp::Complex{};channel.envB[q]=low?channel.cepB[q]:dsp::Complex{};channel.detailA[q]=low?dsp::Complex{}:channel.cepA[q];channel.detailB[q]=low?dsp::Complex{}:channel.cepB[q];}variant.cepstralFft.transform(channel.envA,false);variant.cepstralFft.transform(channel.envB,false);variant.cepstralFft.transform(channel.detailA,false);variant.cepstralFft.transform(channel.detailB,false);
    channel.smoothEnvelope+=0.15f*(envelopeBlend_.load()-channel.smoothEnvelope);channel.smoothDetail+=0.15f*(detailBlend_.load()-channel.smoothDetail);channel.smoothPhase+=0.15f*(phaseBlend_.load()-channel.smoothPhase);const auto mode=static_cast<PhaseMode>(std::clamp(phaseMode_.load(),0,3));for(std::size_t k=0;k<n;++k){const float env=channel.envA[k].real()+channel.smoothEnvelope*(channel.envB[k].real()-channel.envA[k].real());const float detail=channel.detailA[k].real()+channel.smoothDetail*(channel.detailB[k].real()-channel.detailA[k].real());const float magnitude=std::exp(std::clamp(env+detail,-20.0f,20.0f));const float pa=std::atan2(spectrum[k].imag(),spectrum[k].real()),pb=std::atan2(b[k].imag(),b[k].real());float phase=pa+channel.smoothPhase*(pb-pa);if(mode==PhaseMode::Inverted)phase=pb+channel.smoothPhase*(pa-pb);else if(mode==PhaseMode::AOnly)phase=pa;else if(mode==PhaseMode::BOnly)phase=pb;spectrum[k]=std::polar(magnitude,dsp::wrapPhase(phase));}
}
} // namespace madron::cepstral
